<template><view class="page"><view v-if="loggedIn"><view class="profile"><text class="name">{{staff.name||'调度员'}}</text><text>{{staff.staffNo||staff.mobile}}</text></view><view class="menu"><view @click="go('/pages/order/list')">订单管理 <text>›</text></view><view @click="go('/pages/driver/list')">司机列表 <text>›</text></view><view @click="go('/pages/customer/list')">客户管理 <text>›</text></view></view><button class="logout" @click="logout">退出登录</button></view><view v-else class="login"><text class="title">员工登录</text><input v-model="username" placeholder="工号或手机号"/><input v-model="password" password placeholder="密码"/><button @click="login">登录</button></view></view></template>
<script>import{api}from'@/api/index.js';export default{data(){return{staff:{},loggedIn:false,username:'',password:''}},onShow(){this.loggedIn=!!uni.getStorageSync('token');this.staff=uni.getStorageSync('userInfo')||{}},methods:{async login(){try{const r=await api.login({username:this.username,password:this.password});uni.setStorageSync('token',r.data.token);uni.setStorageSync('userInfo',r.data.staff);this.staff=r.data.staff;this.loggedIn=true}catch(e){console.error(e)}},async logout(){try{await api.logout()}catch(e){console.error(e)}finally{uni.removeStorageSync('token');uni.removeStorageSync('userInfo');this.staff={};this.loggedIn=false}},go(url){uni.navigateTo({url})}}}</script>
<style scoped>.page{min-height:100vh;padding:24rpx;background:#f5f5f5;box-sizing:border-box}.profile{display:flex;flex-direction:column;gap:14rpx;padding:44rpx;color:#fff;background:#1890ff;border-radius:16rpx}.name{font-size:38rpx;font-weight:700}.menu{margin-top:24rpx;background:#fff;border-radius:14rpx}.menu view{display:flex;justify-content:space-between;padding:30rpx;border-bottom:1rpx solid #eee}.logout{margin-top:36rpx;color:#f5222d;background:#fff}.login{margin-top:160rpx;padding:46rpx 34rpx;background:#fff;border-radius:18rpx}.title{display:block;margin-bottom:36rpx;text-align:center;font-size:38rpx;font-weight:700}.login input{padding:22rpx;margin-bottom:20rpx;background:#f5f5f5;border-radius:10rpx}.login button{color:#fff;background:#1890ff}</style>
